 const display=`<div class="settings-grid"><label class="form-field">テーマ<select id="theme-mode">${[['dark','ダーク'],['light','ライト'],['system','端末に合わせる']].map(([k,v])=>`<option value="${k}" ${(config.theme||'dark')===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="form-field">スキン<span class="skin-controls"><select id="skin-mode">${SKINS.map(({id:k,name:v})=>`<option value="${k}" ${(config.skin||'graphite')===k?'selected':''}>${v}</option>`).join('')}</select><button type="button" data-action="skin-gallery">一覧</button></span></label></div><label class="glass-preference"><input id="glass-effects" type="checkbox" ${config.glassEffects!==false?'checked':''} ${glassSkin(config.skin||'graphite')?'':'disabled'}>ガラスの反射</label><h3>アプリ内のロゴ</h3><div class="logo-options">${['original','A','B','C','D'].map(id=>`<button data-action="logo-choice" data-id="${id}" aria-pressed="${(config.logoChoice||'original')===id}"><img src="${id==='original'?'/icons/focus.svg':'/icons/focus-'+id+'.png'}" alt=""><small>${id==='original'?'現在':id}</small></button>`).join('')}</div><h3>完了の動き</h3><div class="motion-options"><label class="form-field"><select id="completion-motion" aria-label="完了の動き">${[['pop','ポップ'],['ripple','波紋'],['rise','浮上'],['none','動きなし']].map(([k,v])=>`<option value="${k}" ${(config.completionMotion||'pop')===k?'selected':''}>${v}</option>`).join('')}</select></label><button class="primary-button motion-preview" data-action="motion-preview">完了</button></div><h3>ホームの表示</h3><div class="settings-grid">${['progress','logs'].map(k=>`<label class="panel-options"><input type="checkbox" data-visible="${k}" ${!(config.dashboardHidden||[]).includes(k)?'checked':''}>${labels[k]}</label>`).join('')}</div>`;
 const totals=`<div class="data-inventory"><div><strong>${routines().length}</strong><small>タスク</small></div><div><strong>${data.logs.length}</strong><small>記録</small></div><div><strong>${data.sourceTables.length}</strong><small>元データ</small></div></div><div class="actions"><button data-action="inventory" data-kind="logs">データ一覧</button><button data-action="export">JSON</button><button data-action="portable">移行用ZIP</button></div><div class="actions"><button data-action="recovery">復元ポイント</button><button data-action="backup-now">PCへ控えを保存</button></div><p class="setting-note" id="device-backup-state">${esc(deviceCheckpoint?.message||'この端末に保存')}</p><label class="form-field">Notionから追加<input id="migration" type="file" accept=".json"></label><details class="settings-section"><summary>全体を復元（置き換え）</summary><label class="form-field">FocusのJSON<input id="restore" type="file" accept=".json"></label></details>${(data.migrations||[]).map(m=>`<div class="data-audit">Notion移行 · 記録${m.summary?.logs||0}件${m.summary?.unfinishedLogs?' · 未終了 '+m.summary.unfinishedLogs+'件を元データに保管':''}</div>`).join('')}`;
 const connections=`${SYNC_ENABLED?`<h3>端末間同期</h3><p class="setting-note" id="sync-detail" role="status">${esc(sync?.message||'同期オフ')}</p>${sync?.enabled?'<div class="actions"><button data-action="sync-now">今すぐ同期</button><button data-action="sync-off">切断</button></div>':'<form id="sync-form" class="sync-form"><input type="password" name="key" required minlength="43" maxlength="43" autocomplete="off" placeholder="同期キー" aria-label="同期キー"><button>接続</button></form>'}${sync?.conflict?'<p class="error">同じ項目に変更があります。</p><div class="actions"><button data-action="sync-local">競合箇所はこの端末</button><button data-action="sync-remote">競合箇所は同期先</button></div>':''}`:''}${googleSettings()}${planningSettings()}`;
 const help=`<h3>タイマー終了の通知</h3><p id="timer-notification-state" class="setting-note">${esc(timerNotifications.status)}</p><div class="actions"><button data-action="notifications-enable">通知を許可</button><button data-action="notifications-disable">オフ</button></div><ol class="help-list"><li>「＋ 選ぶ」で登録済みのタスクとやることを選びます。</li><li>今日のタスクを選択し、計測欄でモードを決めて開始します。</li><li>「完了」で合計の作業時間を記録します。タイマーが0になった後も計測を続けます。ポモドーロの休憩は作業時間に含めません。</li><li>今日のタスク右端の⠿を日程へドラッグして配置・移動できます。未配置でもタップで時刻と時間長を調整できます。</li><li>忘れた記録は「昨日の記録」または「未記録の予定」から補えます。</li><li>各画面の「配置」を押すと、ブロックを直接ドラッグできます。</li><li>PCのSpaceキーで開始・一時停止。入力中とダイアログ表示中は反応しません。</li></ol><p class="data-help">計測は開始時刻から復元します。Safariを閉じたり端末がスリープしても、再表示時に経過を復元します。WindowsのChrome・Edgeでは計測中の小画面表示アイコンで画面外へタイマーを表示できます。小窓を閉じても計測は続きます。iPhone・iPadは通常画面を使います。終了時は音なしで通知します。iPhone・iPadの端末通知はホーム画面への追加と通知許可が必要です。アプリの完全終了・OSのスリープ中は通知を保証できません。再表示時に終了を表示します。</p>${pwaSettings()}<p class="setting-note" id="focus-release">Focus ${FOCUS_RELEASE}</p>`;
