const calendarDrag=new CalendarDrag({root:$('#workspace'),preview:(id,start,minutes)=>{const e=calendarTask(data,config.routines,id);if(!e)throw Error('予定が見つかりません。');const next=scheduledEvent(data,config.routines,id,{date:e.date,start:timeOf(start),minutes:minutes??e.duration??minutesOf(e.end)-minutesOf(e.start)},externalGoogle(),session);return {...next,overlapMarkup:overlapMarkup(next,[...data.events.filter(e=>e.id!==id),...externalGoogle()])};},commit:(id,start,options={})=>{const e=calendarTask(data,config.routines,id);if(!e)throw Error('予定が見つかりません。');movePlan(id,{date:e.date,start:timeOf(start),minutes:options.minutes??e.duration??minutesOf(e.end)-minutesOf(e.start)},options);},onError:message=>{calendarError=message;const target=$('#calendar-message');if(target)target.textContent=message;else error(message);},onEnd:()=>{if(googlePendingReplan)googleChanged();}});
window.addEventListener('hashchange',render);document.addEventListener('close',e=>{if(e.target.id==='edit-dialog'){dialogEditing=false;sync?.changed();if(googlePendingReplan)googleChanged();}},true);
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;try{
 if(f.id==='task-form'){const id=f.dataset.id,old=config.routines.find(r=>r.id===id),r={...old,id,title:f.elements.title.value.trim(),category:f.elements.category.value,minutes:Number(f.elements.minutes.value),preferredStart:f.elements.preferredStart.value,preferredEnd:f.elements.preferredEnd.value,prepareBefore:Number(f.elements.prepareBefore.value),prepareAfter:Number(f.elements.prepareAfter.value),activities:old?.activities||[]};if(!validRoutine(r))throw Error('名前・時間帯・時間長・準備時間を確認してください。');config.routines=old?config.routines.map(t=>t.id===id?r:t):[...config.routines,r];for(const day of new Set((data.focusPlans||[]).filter(p=>p.date>=dateKey()).map(p=>p.date)))replan(day);save({settings:true});render();if(old)$('#edit-dialog').close();else taskEditor(id);}
 if(f.id==='activity-form'){const r=config.routines.find(r=>r.id===f.dataset.routine),a={id:f.dataset.id,title:f.elements.title.value.trim(),minutes:Number(f.elements.minutes.value)},next={...r,activities:r.activities.some(x=>x.id===a.id)?r.activities.map(x=>x.id===a.id?{...x,...a}:x):[...r.activities,a]};if(!validRoutine(next))throw Error('やることと1〜1440分の時間長を確認してください。');config.routines=config.routines.map(x=>x.id===r.id?next:x);for(const day of new Set((data.focusPlans||[]).filter(p=>p.routineId===r.id&&p.date>=dateKey()).map(p=>p.date)))replan(day);save({settings:true});$('#detail-dialog').close();render();if($('#edit-dialog').querySelector('#task-form'))taskEditor(r.id);else taskPicker();}
 if(f.id==='log-form'){if(f.dataset.saved==='true')return;const old=data.logs.find(l=>l.id===f.dataset.id),date=f.elements.date.value,start=f.elements.start.value,minutes=Number(f.elements.duration.value),title=f.elements.title.value.trim(),{r,a}=item(f.elements.routine.value,f.elements.activity.value);if(!title||title.length>2000||!validDate(date)||date>dateKey()||(!validTime(start)&&!(old&&!old.start&&!start))||!validMinutes(minutes,Math.max(1440,old?.minutes||0)))throw Error('内容・今日以前の日付・開始・整数の時間長を確認してください。');const unlink=f.dataset.unlink==='true',log={...old,id:old?.id||uid(),title,category:old?.category||r?.category||'learning',date,...(start?{start}:{}),minutes,note:old?.note||'',routineId:r?.id||(!unlink?old?.routineId:undefined),activityId:a?.id||(!unlink?old?.activityId:undefined),eventId:unlink?undefined:f.dataset.event||old?.eventId};if(old?.minutes!==minutes)delete log.elapsedSeconds;if(start&&(!old||old.date!==date||old.start!==start||old.minutes!==minutes)){log.startedAt=new Date(date+'T'+start+':00+09:00').toISOString();log.endedAt=new Date(Date.parse(log.startedAt)+(log.elapsedSeconds??minutes*60)*1000).toISOString();log.entryMode='manual';if(Date.parse(log.endedAt)>Date.now()+60000)throw Error('実施済みの時間を指定してください。');}const next={...data,logs:old?data.logs.map(l=>l.id===old.id?log:l):[...data.logs,log]};if(!validFocusData(next))throw Error('入力を確認してください。');data=next;f.dataset.saved='true';store.write('focus-manual-draft','');save();$('#edit-dialog').close();render();}
 if(f.id==='plan-form'){movePlan(f.dataset.id,{date:f.elements.date.value,start:f.elements.start.value,minutes:Number(f.elements.duration.value)},{keepScroll:false});$('#edit-dialog').close();}

 if(f.id==='planning-form'){const planning={dayStart:f.elements.dayStart.value,dayEnd:f.elements.dayEnd.value,gapMinutes:Number(f.elements.gapMinutes.value),dailyLimit:Number(f.elements.dailyLimit.value)};if(!validPlanning(planning))throw Error('時間帯・休憩・上限を確認してください。');config.planning=planning;for(const day of new Set((data.focusPlans||[]).filter(p=>p.date>=dateKey()).map(p=>p.date)))replan(day);save({settings:true});settings();render();}
 if(f.id==='sync-form'){await sync.connect(f.elements.key.value.trim());if(google){await google.loadStatus().catch(()=>{});if(google.connected)await google.refresh().catch(()=>{});}if($('#settings-dialog').open)settings();}
 }catch(err){error(err.message);}});
