 const call=async action=>{const response=await fetch('/api/focus-migration',{method:'POST',cache:'no-store',headers:{'Content-Type':'application/json','X-Focus-Local':'1','X-Focus-Environment':FOCUS_ENV},body:JSON.stringify({action})});if(response.status===404)return {available:false};if(!response.ok)throw Error('移行データを読み込めませんでした。設定から再度取り込めます。');return response.json();};
